1	import { useState } from 'react';
2	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3	import { getJson, postJson } from '../../api/http';
4	import { asString, useSearchParam } from '../../url/useSearchParam';
5	import { ClientsToolbar } from '../../slots/defs/clientsToolbar';
6	import { ClientRowActions } from '../../slots/defs/clientRowActions';
7	
8	// A client as the server returns it.
9	export type Client = { id: number; name: string; email: string };
10	
11	// A client must carry a proper email address. Same shape the server enforces (ClientsPost) so the
12	// UI never asks the server to save what the server will reject.
13	export function isValidEmail(email: string): boolean {
14	  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
15	}
16	
17	// The clients page: the whole list of clients plus the form to add one. Server data is read with
18	// useQuery under the ['clients'] key and changed with useMutation + invalidateQueries — never
19	// copied into state, never hand-maintained. The only useState here is the two fields the user is
20	// currently typing into (rule 4).
21	export function ClientsPage() {
22	  const queryClient = useQueryClient();
23	  // The name filter lives in the URL (owned by features/clients/search.slot.tsx). The list reads
24	  // the same key and asks the server for the narrowed list, so it stays a single source of truth —
25	  // no server data copied into state. The key still starts with 'clients', so writes that
26	  // invalidateQueries({ queryKey: ['clients'] }) still refresh it.
27	  const [q] = useSearchParam('clientSearch', asString);
28	  // The sort lives in the URL too (owned by features/clients/sort.slot.tsx). The list reads the
29	  // same key and asks the server for the ordered list, so it stays a single source of truth — no
30	  // server data copied into state or re-sorted by hand. The key still starts with 'clients', so
31	  // writes that invalidateQueries({ queryKey: ['clients'] }) still refresh it.
32	  const [sort] = useSearchParam('clientSort', asString);
33	  const clients = useQuery({
34	    queryKey: ['clients', q, sort],
35	    queryFn: () => {
36	      const params = new URLSearchParams();
37	      if (q) params.set('q', q);
38	      if (sort) params.set('sort', sort);
39	      const qs = params.toString();
40	      return getJson<Client[]>(qs ? `/api/clients?${qs}` : '/api/clients');
41	    },
42	  });
43	
44	  const [name, setName] = useState('');
45	  const [email, setEmail] = useState('');
46	  // The email error message, or null when the field is fine. It covers both a locally-caught bad
47	  // format and a server rejection (a duplicate email — the server is the source of truth for
48	  // uniqueness, since another session may have taken the address).
49	  const [emailError, setEmailError] = useState<string | null>(null);
50	
51	  const create = useMutation({
52	    mutationFn: () => postJson<Client>('/api/clients', { name, email }),
53	    onSuccess: () => {
54	      setName('');
55	      setEmail('');
56	      setEmailError(null);
57	      void queryClient.invalidateQueries({ queryKey: ['clients'] });
58	    },
59	    onError: () => {
60	      setEmailError('That email is already in use.');
61	    },
62	  });
63	
64	  const rows = clients.data ?? [];
65	
66	  return (
67	    <section data-testid="clients">
68	      <form
69	        data-testid="client-form"
70	        onSubmit={(e) => {
71	          e.preventDefault();
72	          if (!isValidEmail(email)) {
73	            setEmailError('Enter a valid email address.');
74	            return;
