          {rows.map((c) => (
            <tr key={c.clientId} data-testid={`top-client-row-${c.clientId}`}>
              <td data-testid="top-client-name">{c.name}</td>
              <td data-testid="top-client-amount">{money(Number(c.amount))}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

